correctedCode:
class Animal {
    String makeSound() {
        return "...";
    }
}

class Dog extends Animal {
    @Override
    String makeSound() {
        return "Woof";
    }
}

public class Main {
    public static void main(String[] args) {
        Animal a = new Dog();
        System.out.println(a.makeSound());
    }
}
